package tritium.minecraft.runtime.render;
import java.util.*;
import org.lwjgl.opengl.GL11;
import tritium.minecraft.runtime.hook.RenderAccess;
import tritium.minecraft.runtime.util.render.*;
public final class BedESPModule extends RenderModule {
 private static final class Bed {final Object foot,head;final double[] box;List<Object> covering=Collections.emptyList();boolean exposed;long broken;Bed(Object foot,Object head,double[] box){this.foot=foot;this.head=head;this.box=box;}}
 private final Map<Object,Bed> beds=new LinkedHashMap<Object,Bed>();private final List<Bed> broken=new ArrayList<Bed>();private Bed first;private boolean active;private Timer timer;private volatile RuntimeException scanFailure;private volatile long epoch;private volatile double rangeSq;
 public BedESPModule(RenderAccess g,Render3D d){super("bedESP",g,d);}
 public void enable(){final long generation=++epoch;timer=new Timer("Tritium BedESP scan",true);timer.scheduleAtFixedRate(new TimerTask(){long last;public void run(){long now=System.currentTimeMillis();if(!enabled||generation!=epoch||!g.inWorld()||Math.abs(now-last)<n("Rate")*1000-10)return;Object scannedWorld=g.world();try{scan(generation);}catch(RuntimeException error){if(enabled&&generation==epoch&&scannedWorld==g.world()&&g.inWorld())scanFailure=error;}last=now;}},0,200);}
 public void disable(){active=false;epoch++;scanFailure=null;if(timer!=null){timer.cancel();timer.purge();timer=null;}synchronized(beds){first=null;beds.clear();broken.clear();}}
 private boolean inRange(Bed b){double a=g.distanceSq(g.player(),g.coord(b.foot,0)+.5,g.coord(b.foot,1)+.5,g.coord(b.foot,2)+.5);if(a<=rangeSq)return true;if(a>rangeSq+25)return false;return g.distanceSq(g.player(),g.coord(b.head,0)+.5,g.coord(b.head,1)+.5,g.coord(b.head,2)+.5)<=rangeSq;}
 private Bed bed(Object foot,Object head){double x=g.coord(foot,0),y=g.coord(foot,1),z=g.coord(foot,2),hx=g.coord(head,0),hz=g.coord(head,2),h=on("Render full block")?1:.5625;return new Bed(foot,head,new double[]{Math.min(x,hx),y,Math.min(z,hz),Math.max(x,hx)+1,y+h,Math.max(z,hz)+1});}
 private void scan(long generation){Object world=g.world();int radius=(int)n("Range"),px=(int)Math.floor(g.pos(g.player(),0)),py=(int)Math.floor(g.pos(g.player(),1)),pz=(int)Math.floor(g.pos(g.player(),2));rangeSq=radius*radius+2;for(int y=radius;y>=-radius;y--)for(int x=-radius;x<=radius;x++)for(int z=-radius;z<=radius;z++){if(!enabled||epoch!=generation||world!=g.world()||!g.inWorld())return;Object pos=g.pos(px+x,py+y,pz+z),state=g.state(pos);if(g.invoke(state,"getBlock")!=g.block("bed")||!"FOOT".equals(String.valueOf(g.invoke(state,"getValue",g.r(g.cls("block.BlockBed"),"PART")))))continue;Object facing=g.invoke(state,"getValue",g.r(g.cls("block.BlockBed"),"FACING")),head=g.invoke(pos,"offset",facing);Bed b=bed(pos,head);if(!inRange(b))continue;synchronized(beds){if(epoch!=generation)return;if(on("Only render first bed")){if(first==null||!first.foot.equals(pos))first=b;return;}if(!beds.containsKey(pos))beds.put(pos,b);}}}
 public void tick(){active=g.bedwars||!g.hypixel||!on("Disable in lobby")||!g.lobby&&!g.bridgePractice;if(scanFailure!=null)throw new IllegalStateException("OpenB4 BedESP scan failed",scanFailure);synchronized(beds){if(first!=null){if(g.blockAt(first.foot)!=g.block("bed")){first.broken=System.currentTimeMillis();broken.add(first);first=null;}else if(!inRange(first))first=null;else if(n("Covering blocks")!=.45)covering(first);}Iterator<Bed> it=beds.values().iterator();while(it.hasNext()){Bed b=it.next();if(g.blockAt(b.foot)!=g.block("bed")){b.broken=System.currentTimeMillis();broken.add(b);it.remove();}else if(!inRange(b))it.remove();else if(n("Covering blocks")!=.45)covering(b);}}}
 private boolean exposed(Object pos){for(int j=0;j<6;j++){Object p=g.invoke(pos,new String[]{"up","down","north","south","east","west"}[j]),block=g.blockAt(p);if(block==g.block("air")||g.instance(block,"block.BlockLiquid"))return true;for(String name:new String[]{"fire","ladder","iron_bars","ender_chest","enchanting_table","skull","anvil","tripwire","vine","flower_pot"})if(block==g.block(name))return true;for(String name:new String[]{"BlockChest","BlockDoor","BlockTrapDoor","BlockFence","BlockFenceGate","BlockWall","BlockStairs"})if(g.instance(block,"block."+name))return true;if(j!=1&&g.instance(block,"block.BlockSlab"))return true;if(j>=2&&block==g.block("end_portal_frame"))return true;}return false;}
 private void covering(Bed b){Object pos=g.invoke(b.foot,"up"),state=g.state(pos);if(g.invoke(state,"getBlock")!=g.block("air"))b.exposed=exposed(b.foot)||exposed(b.head);else{pos=g.invoke(b.head,"up");state=g.state(pos);b.exposed=true;}if(g.invoke(state,"getBlock")==g.block("air")){b.covering=Collections.emptyList();return;}Set<Object> seen=Collections.newSetFromMap(new IdentityHashMap<Object,Boolean>());List<Object> items=new ArrayList<Object>();for(int j=0;j<4;j++){if(j!=0){pos=g.invoke(pos,"up");state=g.state(pos);}Object block=g.invoke(state,"getBlock");if(block==g.block("air"))break;if(seen.contains(block))continue;Object stack=null;if(!on("Show tools only")){Object item=g.invoke(g.cls("item.Item"),"getItemFromBlock",block);if(item!=null)stack=g.make("item.ItemStack",item,1,RenderAccess.i(g.invoke(block,"damageDropped",state)));}else{String tool=null;if(block==g.block("wool"))tool="shears";else if(block==g.block("planks")||block==g.block("log")||block==g.block("log2"))tool="iron_axe";else if(block==g.block("end_stone")||block==g.block("hardened_clay")||block==g.block("stained_hardened_clay"))tool="iron_pickaxe";else if(block==g.block("obsidian"))tool="diamond_pickaxe";if(tool!=null)stack=g.stack(g.item(tool));}if(stack!=null){seen.add(block);items.add(0,stack);}}b.covering=items;}
 public void world(float pt){if(!active)return;synchronized(beds){if(on("Only render first bed")){if(first!=null)render(first,-1,pt);}else for(Bed b:beds.values())render(b,-1,pt);long now=System.currentTimeMillis();Iterator<Bed> it=broken.iterator();while(it.hasNext()){Bed b=it.next();float t=(now-Math.abs(b.broken))/250f;if(t>=1)it.remove();else render(b,(float)(.95-Math.min(t*.95,.95)),pt);}}}
 private void render(Bed bed,float fade,float pt){if(on("Draw beam")){double x=(g.coord(bed.foot,0)+g.coord(bed.head,0))*.5,y=g.coord(bed.foot,1),z=(g.coord(bed.foot,2)+g.coord(bed.head,2))*.5;double[] beam={x+.4,y,z+.4,x+.6,y+75,z+.6};if(draw.visible(beam))draw.beam(x,y,z,75,.1,Theme.FROST.getRGB(0),(fade!=-1?fade:1)*.3f);}if(!draw.visible(bed.box))return;double[] bb=bed.box.clone();for(int j=0;j<6;j++)bb[j]-=g.view(j%3);Render3D.filled(bb,Theme.values()[(int)n("Theme")].getRGB(0),fade!=-1?fade:.42f);if(n("Covering blocks")!=.45)renderCovering(bed,fade,pt);}
 private void renderCovering(Bed bed,float fade,float pt){if(bed.covering.isEmpty())return;double sc=n("Covering blocks");if(g.zooming())sc*=2;if(fade!=-1){double t=fade/.95;if(t<=.55)sc=1.3*Math.exp(-5*(1-t));else sc*=1.3*(1+.3*Math.sin((t-.55)*Math.PI/.3));}double x=(g.coord(bed.foot,0)+g.coord(bed.head,0))*.5+.5,y=g.coord(bed.foot,1)+1,z=(g.coord(bed.foot,2)+g.coord(bed.head,2))*.5+.5;double dx=draw.camera[0]-x,dy=draw.camera[1]-y,dz=draw.camera[2]-z,ds=dx*dx+dy*dy+dz*dz;if(ds<81)sc=Math.max(sc*9/Math.sqrt(ds),sc);double[] v=draw.project(x,y,z,-1);try{if(v==null||v[2]>=1.0003684)return;GL11.glPushMatrix();try{GL11.glScaled(sc,sc,sc);float ix=(float)(v[0]/sc-8*bed.covering.size()),iy=(float)((v[1]-8)/sc);GL11.glDepthFunc(GL11.GL_ALWAYS);int border=bed.exposed&&bed.broken==0?-8327298:0x5a000000;Render3D.roundedBorder(ix-1.5,iy-1.5,ix+16*bed.covering.size()+1.5,iy+17.5,8,0x5a000000,border,border);for(Object stack:bed.covering){g.drawItem(stack,ix,iy);ix+=16;}GL11.glDepthFunc(GL11.GL_LEQUAL);}finally{GL11.glPopMatrix();}}finally{draw.setupCamera(pt);}}
}
